ts_message("chunk #40 `<feder_kmate>` start")
# make list of sites
# for now, ignore some sites
sites <- unique(gsub("_.*", "", colnames(hapfire)))

output_feder_kmate <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/feder_t_test_kmate.tsv",
  sep = ""
)

# delete previous run
# NOTE: suspected — the delete-previous-run guard is commented out, so a rerun
# APPENDS duplicate rows to feder_t_test_kmate.tsv; delete the file (or uncomment
# the guard) before rerunning on the same day.
# check_file_exists(output_feder_kmate)

# check that directory exists
folder_path <- dirname(output_feder_kmate)
if (!dir.exists(folder_path)) {
  dir.create(folder_path, recursive = TRUE, showWarnings = FALSE)
}

# loop over sites
for(site in unique(sites)) {
  print(paste("Site:", site))
  hap_site <- hapfire %>% 
    dplyr::select(starts_with(paste(site, "_", sep = "")))
  
  for(exprep in 1:12) {
    print(paste(Sys.time()," - Rep:", exprep))
    hap_rep <- hap_site %>%
      dplyr::select(ends_with(paste("_", exprep, sep = ""))) %>%
      collect()
    
    # sort names to be in order of generation
    hap_rep <- hap_rep %>%
      relocate(all_of(sort(colnames(hap_rep))))
    
    if (ncol(hap_rep) < 1) {
      print("Need at least one increment. Skipping to next replicate...")
      next
    }
    
    hap_rep <- cbind(gen0$X0_0_0, hap_rep)
    colnames(hap_rep)[1] = paste(site, "_0_", exprep, sep = "")
    
    gens <- as.integer(gsub("_", "", str_extract(colnames(hap_rep), "_[0-9]_")))
    # numerator
    if(ncol(hap_rep) == 2){
      dp <- matrix(unlist(apply((hap_rep), MARGIN = 1, FUN = diff)), ncol = 1)
      dp <- as.data.frame(dp)
      names(dp) <- colnames(hap_rep)[2]
    } else {
      dp <- t(apply((hap_rep), MARGIN = 1, FUN = diff))
    }
    # denominator
    v_i_minus_1 <- (hap_rep)[,-1*ncol(hap_rep)]
    g_i_minus_1 <- gens[-length(gens)]
    # bring it all together
    y_i <- dp/sqrt(2*v_i_minus_1*(1 - v_i_minus_1)*diff(gens))
    # cbind extra info
    # NOTE: suspected — gen0 rows are attached positionally to the collected tray
    # matrix; correct only while the arrow collect returns file order (the header
    # sets arrow.use_threads = FALSE for exactly this reason).
    y_i$chrom <- (gen0$chrom)
    y_i$pos <- (gen0$pos)
    y_i$site <- site
    y_i$rep <- exprep
    
    y_i <- y_i %>% 
      pivot_longer(cols = c(-chrom, -pos, -site, -rep), 
                   names_to = "pool", 
                   values_to = "yi")
    
    append_table(y_i, output_feder_kmate)
    rm(y_i, v_i_minus_1, g_i_minus_1, dp, hap_rep); gc()
  }
}

